function minDeletionsPalindrome(s) {
  const n = s.length;
  const dp = Array.from({length: n}, () => Array(n).fill(0));
  for (let len = 2; len <= n; len++) {
    for (let i = 0; i + len - 1 < n; i++) {
      const j = i + len - 1;
      if (s[i] === s[j]) dp[i][j] = dp[i+1][j-1];
      else dp[i][j] = Math.min(dp[i+1][j], dp[i][j-1]) + 1;
